Index: packages/react/menu/src/menu-ref-stability.test.tsx
===================================================================
--- packages/react/menu/src/menu-ref-stability.test.tsx	
+++ packages/react/menu/src/menu-ref-stability.test.tsx	
@@ -0,0 +1,33 @@
+import * as React from 'react';
+import { render, cleanup } from '@testing-library/react';
+import { afterEach, describe, it, expect } from 'vitest';
+import { Menu, MenuContent, MenuSub, MenuSubTrigger } from './menu';
+
+describe('MenuSubTrigger composed ref stability', () => {
+  afterEach(cleanup);
+
+  it('does not cause an infinite render loop when attaching the ref triggers a render', () => {
+    let renderCount = 0;
+
+    function App() {
+      renderCount++;
+      const [, forceRender] = React.useReducer((c) => c + 1, 0);
+      const ref = React.useCallback((node: HTMLElement | null) => {
+        if (node) forceRender();
+      }, []);
+
+      return (
+        <Menu modal={false}>
+          <MenuContent forceMount>
+            <MenuSub>
+              <MenuSubTrigger ref={ref}>Edit</MenuSubTrigger>
+            </MenuSub>
+          </MenuContent>
+        </Menu>
+      );
+    }
+
+    expect(() => render(<App />)).not.toThrow();
+    expect(renderCount).toBeLessThan(25);
+  });
+});

